DROP TABLE IF EXISTS FlowsOutcome;												
CREATE TABLE FlowsOutcome (												
  InstitutionID VARCHAR(8),												
  DegreeAwardCode VARCHAR(2),												
  DegreeAwardName VARCHAR(100),												
  CIPCode VARCHAR(2),												
  Cohort VARCHAR(9),												
  IndustryID VARCHAR(10),												
  IndustryName VARCHAR(100),												
  YearsPostgrad INTEGER,												
  Instate BOOL,												
  Flow INTEGER,												
  PRIMARY KEY (InstitutionID, DegreeAwardCode, CIPCode, Cohort, IndustryID, YearsPostgrad, Instate)												
);												
